1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import { createGoalSchema, updateGoalSchema } from "@paperclipai/shared";
4	import { trackGoalCreated } from "@paperclipai/shared/telemetry";
5	import { validate } from "../middleware/validate.js";
6	import { goalService, logActivity } from "../services/index.js";
7	import { assertCompanyAccess, getActorInfo } from "./authz.js";
8	import { getTelemetryClient } from "../telemetry.js";
9	import type { Handler } from "../http/types.js";
10	import { expressHandler } from "../http/express-adapter.js";
11	
12	export function goalRoutes(db: Db) {
13	  const router = Router();
14	  const svc = goalService(db);
15	
16	  const listGoals: Handler = async (ctx) => {
17	    const companyId = ctx.param("companyId")!;
18	    assertCompanyAccess(ctx, companyId);
19	    const result = await svc.list(companyId);
20	    return Response.json(result);
21	  };
22	
23	  const getGoal: Handler = async (ctx) => {
24	    const id = ctx.param("id")!;
25	    const goal = await svc.getById(id);
26	    if (!goal) {
27	      return Response.json({ error: "Goal not found" }, { status: 404 });
28	    }
29	    assertCompanyAccess(ctx, goal.companyId);
30	    return Response.json(goal);
31	  };
32	
33	  const createGoal: Handler = async (ctx) => {
34	    const companyId = ctx.param("companyId")!;
35	    assertCompanyAccess(ctx, companyId);
36	    const body = await ctx.json();
37	    const goal = await svc.create(companyId, body);
38	    const actor = getActorInfo(ctx);
39	    await logActivity(db, {
40	      companyId,
41	      actorType: actor.actorType,
42	      actorId: actor.actorId,
43	      agentId: actor.agentId,
44	      action: "goal.created",
45	      entityType: "goal",
46	      entityId: goal.id,
47	      details: { title: goal.title },
48	    });
49	    const telemetryClient = getTelemetryClient();
50	    if (telemetryClient) {
51	      trackGoalCreated(telemetryClient, { goalLevel: goal.level });
52	    }
53	    return Response.json(goal, { status: 201 });
54	  };
55	
56	  const updateGoal: Handler = async (ctx) => {
57	    const id = ctx.param("id")!;
58	    const existing = await svc.getById(id);
59	    if (!existing) {
60	      return Response.json({ error: "Goal not found" }, { status: 404 });
61	    }
62	    assertCompanyAccess(ctx, existing.companyId);
63	    const body = await ctx.json();
64	    const goal = await svc.update(id, body);
65	    if (!goal) {
66	      return Response.json({ error: "Goal not found" }, { status: 404 });
67	    }
68	
69	    const actor = getActorInfo(ctx);
70	    await logActivity(db, {
71	      companyId: goal.companyId,
72	      actorType: actor.actorType,
73	      actorId: actor.actorId,
74	      agentId: actor.agentId,
75	      action: "goal.updated",
76	      entityType: "goal",
77	      entityId: goal.id,
78	      details: body,
79	    });
80	
81	    return Response.json(goal);
82	  };
83	
84	  const deleteGoal: Handler = async (ctx) => {
85	    const id = ctx.param("id")!;
86	    const existing = await svc.getById(id);
87	    if (!existing) {
88	      return Response.json({ error: "Goal not found" }, { status: 404 });
89	    }
90	    assertCompanyAccess(ctx, existing.companyId);
91	    const goal = await svc.remove(id);
92	    if (!goal) {
93	      return Response.json({ error: "Goal not found" }, { status: 404 });
94	    }
95	
96	    const actor = getActorInfo(ctx);
97	    await logActivity(db, {
98	      companyId: goal.companyId,
99	      actorType: actor.actorType,
100	      actorId: actor.actorId,
101	      agentId: actor.agentId,
102	      action: "goal.deleted",
103	      entityType: "goal",
104	      entityId: goal.id,
105	    });
106	
107	    return Response.json(goal);
108	  };
109	
110	  // Storage is not used by any goal handler; supply a sentinel to satisfy AdapterDeps.
111	  const storageSentinel = new Proxy({} as import("../storage/types.js").StorageService, {
112	    get(_target, prop) {
113	      throw new Error(`goal handler unexpectedly accessed storage.${String(prop)}`);
114	    },
115	  });
116	
117	  router.get("/companies/:companyId/goals", expressHandler(listGoals, { db, storage: storageSentinel }));
118	  router.get("/goals/:id", expressHandler(getGoal, { db, storage: storageSentinel }));
119	  router.post("/companies/:companyId/goals", validate(createGoalSchema), expressHandler(createGoal, { db, storage: storageSentinel }));
120	  router.patch("/goals/:id", validate(updateGoalSchema), expressHandler(updateGoal, { db, storage: storageSentinel }));
121	  router.delete("/goals/:id", expressHandler(deleteGoal, { db, storage: storageSentinel }));
122	
123	  return router;
124	}
